    {nested && <Dialog title="Nested focus fixture" returnFocus={readerFallback} onClose={() => setNested(false)}><details><summary>Nested disclosure</summary><button>Nested control</button></details><button onClick={() => setNestedInvoker(false)}>Remove parent invoker</button></Dialog>}
  </>;
